            | (Some ({ FStarC_Custard_Syntax.dt_name = tmp2; dt_params = tmp3; dt_body = FStarC_Custard_Syntax.TAbstract; dt_flags = tmp4; _ })) -> (let tmp5 = (FStarC_Custard_Syntax.string_of_name n) in
