    | (FStarC_Custard_Syntax.EMatch (u__1, u__2)) -> true
    | (FStarC_Custard_Syntax.EIf (u__1, u__2, u__3)) -> true
    | (FStarC_Custard_Syntax.ESeq (u__1, u__2)) -> true
    | (FStarC_Custard_Syntax.EWhile (u__1, u__2)) -> true
