    | FStarC_Custard_Syntax.TExn -> (let tmp = (!(nonplain_tbl)) in
      (FStarC_HashTable.FStarC_HashTable_hashtbl_make__0.mem tmp "Prims.exn"))
    | (FStarC_Custard_Syntax.TRef (FStarC_Custard_Syntax.RGc, tmp)) -> (let tmp1 = (!(nonplain_tbl)) in
