let rec cell_dead_branch (x : string) (br : (FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) : bool =
  (match br with
    | (tmp, g, b) -> (let tmp1 = (match g with
          | (Some (g1)) -> (cell_dead x g1)
          | None -> true
