    | (FStarC_Custard_Syntax.EProj (a, tmp, tmp1)) -> (cell_dead x a)
    | (FStarC_Custard_Syntax.EDiscrim (a, tmp)) -> (cell_dead x a)
    | (FStarC_Custard_Syntax.ECast (a, tmp)) -> (cell_dead x a)
    | (FStarC_Custard_Syntax.ECoerce (a, tmp)) -> (cell_dead x a)
