  let e' = (match (e).FStarC_Custard_Syntax.e with
      | (FStarC_Custard_Syntax.EOp ({ FStarC_Custard_Syntax.po_op = FStarC_Custard_Syntax.BufWrite; po_ty = tmp; _ }, ({ FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EVar (y)); ty = tmp1; eff = tmp2; _ } :: (tmp3 :: (tmp4 :: []))))) when ((=) y x) -> (FStarC_Custard_Syntax.EConst (FStarC_Custard_Syntax.CUnit))
