      | (FStarC_Custard_Syntax.ESeq (a, b)) -> (let tmp = (go a) in
        let tmp1 = (go b) in
        let tmp2 = (tmp, tmp1) in
        (FStarC_Custard_Syntax.ESeq ((match tmp2 with (custard_tup, _) -> custard_tup), (match tmp2 with (_, custard_tup) -> custard_tup))))
      | (FStarC_Custard_Syntax.EWhile (a, b)) -> (let tmp = (go a) in
        let tmp1 = (go b) in
        let tmp2 = (tmp, tmp1) in
        (FStarC_Custard_Syntax.EWhile ((match tmp2 with (custard_tup, _) -> custard_tup), (match tmp2 with (_, custard_tup) -> custard_tup))))
      | (FStarC_Custard_Syntax.EApp (h, es)) -> (let tmp = (go h) in
